// 세션(모델)이 쓰는 노트 도구 — 목록·제안·완료 제안, 사용자가 시킨 추가·완료·수정·삭제·되돌리기, 대화로 받은 제안 (spec AGENT.md 1~3절)
import type { EngineInterface, On } from 'claude-code'

import { isoAt, newId, openItems } from './note'
import type { Item, Note, Proposal } from './note'
import { describe, refOf } from './tell'
import {
  acceptIn,
  completeIn,
  editIn,
  forgetItem,
  liveProposals,
  readNote,
  removeIn,
  reopenIn,
  saveChange,
} from './view'

const NAME = 'note'
const CALLED = 'mcp__session-note__note'

// 제안 기준과 완료 대조 규칙은 이 설명문에 고정한다 — 매 답변 노트를 넣지 않는다(성공 기준 ③)
const DESCRIPTION = `The session note: a short list of things to do or check in this session, shared with the user. The user sees it above the prompt and in a side pane, and can add, edit, complete or delete items there; those changes reach you as messages starting with [session-note]. Items and proposals are named by an 8-character ref such as [a1b2c3d4].

Actions:
- list: the whole note (open items with details, done items, your proposals still waiting).
- propose: suggest a new item (title, optional body). It waits on the user's band until they add or dismiss it.
- propose_done: suggest that an open item is done (id). The user completes it or says not yet.
- add: add an item (title, optional body) — only when the user tells you to note something.
- complete: complete an item (id) — only when the user tells you it is done.
- edit: change an item's title and/or body (id, title, body; an empty body clears it) — only when the user tells you to.
- delete: delete an item (id) — only when the user tells you to.
- reopen: reopen a done item (id) — only when the user tells you it is not done.
- accept: accept a waiting proposal (id) — when the user answers it in the conversation ("keep it").

Never edit, delete or reopen items on your own. To change an item, edit it; do not add a new item in its place.

When to propose: only what the conversation clearly put off for later ("later", "let's skip that for now") and questions left without a conclusion ("is this right?", "we should check that"). Do not propose work you are about to do now, details you may decide yourself, or steps of your own plan. Never ask in your reply whether to add something to the note, and do not point the user to your proposals; they see them on the band. Propose and move on.

Completion check: when you finish a piece of work, and when the user asks you to check the note, compare the open items with what was done. For an item that looks done, use propose_done; never complete it yourself unless the user tells you to. After finishing a piece of work, if open items remain, mention them briefly at the end of your reply. Do not check the note on every turn.`

const SCHEMA = {
  type: 'object',
  properties: {
    action: {
      type: 'string',
      enum: ['list', 'propose', 'propose_done', 'add', 'complete', 'edit', 'delete', 'reopen', 'accept'],
    },
    title: { type: 'string', description: 'The item title, one short line (propose, add, edit).' },
    body: { type: 'string', description: 'Optional details (propose, add, edit).' },
    id: {
      type: 'string',
      description: 'The 8-character ref of an item or proposal (propose_done, complete, edit, delete, reopen, accept).',
    },
  },
  required: ['action'],
} as const

type Answer = { result: string } | { deny: string }

const textOf = (value: unknown) => (typeof value === 'string' ? value.trim() : '')

// [a1b2c3d4]·a1b2c3d4·id 전체 모두 받는다
const refIn = (value: unknown) => textOf(value).replace(/^\[|\]$/g, '')

const sameRef = (id: string, ref: string) => ref !== '' && (id === ref || refOf(id) === ref)

const named = (item: Item) => `[${refOf(item.id)}] "${item.title}"`

const unsaved: Answer = { deny: "Couldn't save the note (or it is not open yet). Try again later." }

export function registerTool($: EngineInterface) {
  return $.tool.register({ name: NAME, description: DESCRIPTION, inputSchema: SCHEMA, isDeferred: false })
}

export function serveTool(on: On) {
  on('tool.call', { tool: CALLED }, async ($, e) => answer($, e as unknown as Record<string, unknown>)).catch(() => ({
    deny: 'The note tool failed. Try again later.',
  }))
}

async function answer($: EngineInterface, args: Record<string, unknown>): Promise<Answer> {
  const action = textOf(args['action'])
  if (action === 'list') return { result: describe(await readNote($), true) }
  if (action === 'propose') return propose($, textOf(args['title']), textOf(args['body']))
  if (action === 'add') return add($, textOf(args['title']), textOf(args['body']))
  const ref = refIn(args['id'])
  if (action === 'propose_done') return proposeDone($, ref)
  if (action === 'complete') return complete($, ref)
  if (action === 'edit') return edit($, ref, textOf(args['title']), bodyIn(args['body']))
  if (action === 'delete') return remove($, ref)
  if (action === 'reopen') return reopen($, ref)
  if (action === 'accept') return accept($, ref)
  return {
    deny: `Unknown action "${action}". Use list, propose, propose_done, add, complete, edit, delete, reopen or accept.`,
  }
}

const openItem = (n: Note, ref: string) => openItems(n).find(item => sameRef(item.id, ref))

const anyItem = (n: Note, ref: string) => n.items.find(item => sameRef(item.id, ref))

// edit의 내용 — 주지 않았으면 그대로 두고, 빈 글이면 비운다
const bodyIn = (value: unknown) => (typeof value === 'string' ? value.trim() : undefined)

async function propose($: EngineInterface, title: string, body: string): Promise<Answer> {
  if (title === '') return { deny: 'A proposal needs a title.' }
  const current = await readNote($)
  const same = (other: string) => other.toLowerCase() === title.toLowerCase()
  if (openItems(current).some(item => same(item.title))) return { result: `"${title}" is already an open item.` }
  if (current.proposals.some(p => p.kind === 'new' && same(p.title)))
    return { result: `"${title}" is already proposed and waiting for the user.` }
  const proposal: Proposal = { id: newId(), kind: 'new', title, body, proposedAt: isoAt(await $.clock.now()) }
  const saved = await saveChange($, n => ({ ...n, proposals: [...n.proposals, proposal] }))
  if (saved === null) return unsaved
  return {
    result: `Proposed "${title}" [${refOf(proposal.id)}]. It waits on the user's band; do not mention it in your reply.`,
  }
}

async function proposeDone($: EngineInterface, ref: string): Promise<Answer> {
  const item = openItem(await readNote($), ref)
  if (item === undefined) return { deny: `No open item [${ref}]. Use list to see the refs.` }
  if ((await readNote($)).proposals.some(p => p.kind === 'done' && p.itemId === item.id))
    return { result: `${named(item)} is already proposed as done and waiting for the user.` }
  const proposal: Proposal = { id: newId(), kind: 'done', itemId: item.id, proposedAt: isoAt(await $.clock.now()) }
  const saved = await saveChange($, n => ({ ...n, proposals: [...n.proposals, proposal] }))
  if (saved === null) return unsaved
  return { result: `Proposed ${named(item)} as done. It waits on the user's band; do not mention it in your reply.` }
}

async function add($: EngineInterface, title: string, body: string): Promise<Answer> {
  if (title === '') return { deny: 'An item needs a title.' }
  const item: Item = {
    id: newId(),
    title,
    body,
    source: 'instruction',
    status: 'open',
    createdAt: isoAt(await $.clock.now()),
    doneAt: null,
  }
  const saved = await saveChange($, n => ({ ...n, items: [...n.items, item] }))
  if (saved === null) return unsaved
  return { result: `Added ${named(item)}.` }
}

async function complete($: EngineInterface, ref: string): Promise<Answer> {
  const item = openItem(await readNote($), ref)
  if (item === undefined) return { deny: `No open item [${ref}]. Use list to see the refs.` }
  const at = isoAt(await $.clock.now())
  const saved = await saveChange($, n => completeIn(n, item.id, at))
  if (saved === null) return unsaved
  return { result: `Completed ${named(item)}.` }
}

async function edit($: EngineInterface, ref: string, title: string, body: string | undefined): Promise<Answer> {
  const item = anyItem(await readNote($), ref)
  if (item === undefined) return { deny: `No item [${ref}]. Use list to see the refs.` }
  if (title === '' && body === undefined) return { deny: 'Give a new title or body to edit.' }
  const saved = await saveChange($, n => editIn(n, item.id, title, body))
  if (saved === null) return unsaved
  const edited = saved.items.find(one => one.id === item.id)
  if (edited === undefined) return { deny: `The item [${ref}] is gone.` }
  return { result: `Edited ${named(edited)}.` }
}

async function remove($: EngineInterface, ref: string): Promise<Answer> {
  const item = anyItem(await readNote($), ref)
  if (item === undefined) return { deny: `No item [${ref}]. Use list to see the refs.` }
  const saved = await saveChange($, n => removeIn(n, item.id))
  if (saved === null) return unsaved
  await forgetItem($, item.id)
  return { result: `Deleted ${named(item)}.` }
}

async function reopen($: EngineInterface, ref: string): Promise<Answer> {
  const item = anyItem(await readNote($), ref)
  if (item === undefined) return { deny: `No item [${ref}]. Use list to see the refs.` }
  if (item.status === 'open') return { result: `${named(item)} is already open.` }
  const saved = await saveChange($, n => reopenIn(n, item.id))
  if (saved === null) return unsaved
  return { result: `Reopened ${named(item)}.` }
}

async function accept($: EngineInterface, ref: string): Promise<Answer> {
  const proposal = liveProposals(await readNote($)).find(p => sameRef(p.id, ref))
  if (proposal === undefined) return { deny: `No waiting proposal [${ref}]. Use list to see the refs.` }
  const at = isoAt(await $.clock.now())
  const itemId = newId()
  const saved = await saveChange($, n => {
    const latest = n.proposals.find(p => p.id === proposal.id)
    return latest === undefined ? n : acceptIn(n, latest, at, itemId)
  })
  if (saved === null) return unsaved
  const item = saved.items.find(one => one.id === (proposal.kind === 'new' ? itemId : proposal.itemId))
  if (item === undefined) return { deny: `The proposal [${ref}] is gone.` }
  return { result: proposal.kind === 'new' ? `Added ${named(item)}.` : `Completed ${named(item)}.` }
}

files.hooks/view.ts:
// 띠·패널이 그리는 값($.state)과 노트를 바꾸는 동작 — 바꿀 때마다 파일에 저장하고, 실패하면 화면을 그대로 둔다
import { atom, read, update } from 'claude-code'
import type { EngineInterface } from 'claude-code'

import type { Draft, Item, Note, Proposal, View } from '../types'
import { emptyNote, isoAt, newId } from './note'

export { doneItems, liveProposals, openItems } from './note'
import { keepCopy, loadNote, notePath, saveNote } from './store'
import { tell, told } from './tell'
import type { Text } from './text'

export type { Draft, View } from '../types'

export const PANE = 'session-note'

// 모듈을 불러올 때마다 새로 정해진다 — 다시 켜지기 전의 초안을 알아보는 표시
export const LOAD = newId()

const blankView = (): View => ({
  load: LOAD,
  openId: null,
  armedId: null,
  showDone: false,
  showAll: false,
  adding: null,
  editing: null,
  editKey: LOAD,
})

const session = atom({ plugin: 'session-note', key: 'session' } as const, null)
const note = atom({ plugin: 'session-note', key: 'note' } as const, { version: 1, items: [], proposals: [] })
const paneOpen = atom({ plugin: 'session-note', key: 'paneOpen' } as const, false)
const viewAtom = atom({ plugin: 'session-note', key: 'view' } as const, blankView())

// 엔진은 다른 파일로 넘긴 $를 function 선언 안에서만 따라가므로, $를 받는 공용 함수는 모두 function으로 쓴다
export async function readView($: EngineInterface): Promise<View> {
  const view = await read($, viewAtom)
  return view.load === LOAD ? view : blankView()
}

export async function setView($: EngineInterface, change: (view: View) => View) {
  await update($, viewAtom, view => change(view.load === LOAD ? view : blankView()))
}

// 엔진은 상태 값을 그 값을 정의한 파일 안에서만 읽고 쓰게 하므로, 다른 파일은 아래 함수로 다룬다
export async function readNote($: EngineInterface): Promise<Note> {
  return read($, note)
}

export async function isPaneOpen($: EngineInterface): Promise<boolean> {
  return read($, paneOpen)
}

// 세션의 노트를 화면 값으로 올리고, 패널이 지금 열려 있는지 맞춘다. 앞 세션의 초안·펼침은 버린다
async function showSession($: EngineInterface, opened: { id: string; path: string; overwrite: boolean }, shown: Note) {
  await update($, session, () => opened)
  await update($, note, () => shown)
  await update($, viewAtom, () => blankView())
  const panes = await $.ui.panes()
  await update($, paneOpen, () => panes.some(pane => pane.id === PANE))
}

// 세션 시작·전환 때 그 세션의 노트 파일을 연다. 읽을 수 없으면 사본을 남기고 빈 노트로 시작한다(spec DATA.md 3절)
export async function openSession($: EngineInterface, text: Text, id: string): Promise<Note> {
  const path = await notePath($, id)
  const loaded = await loadNote($, path)
  if (loaded.ok) {
    await showSession($, { id, path, overwrite: false }, loaded.note)
    return loaded.note
  }
  const copy = loaded.text === undefined ? null : await keepCopy($, path, loaded.text, isoAt(await $.clock.now()))
  if (copy === null) $.ui.log(`could not keep a copy of ${path}: ${loaded.reason}`, { to: 'debug' })
  else $.ui.toast(text.unreadable)
  // 사본을 못 남겼으면 원본을 지킨다 — 저장은 실패로 둔다
  await showSession($, { id, path, overwrite: copy !== null }, emptyNote())
  return emptyNote()
}

// 패널이 닫혔다 — 초안을 버린다
export async function paneClosed($: EngineInterface) {
  await update($, paneOpen, () => false)
  await dropDrafts($)
}

// 초안을 모두 버린다(패널 닫기 등)
export async function dropDrafts($: EngineInterface) {
  await setView($, view => ({ ...view, adding: null, editing: null, armedId: null }))
}

export async function openPane($: EngineInterface, title: string) {
  await $.ui.open({ id: PANE, title })
  await update($, paneOpen, () => true)
}

// 수정 칸의 key — 끝의 editKey는 수정을 저장할 때마다 바뀐다(types View.editKey)
export const editFieldKey = (field: keyof Draft, editKey: string) => `edit-${field}-${editKey}`

// [수정]을 누르면 그 항목을 수정 칸으로 바꾸고, 패널이 키보드를 받아 제목 칸 끝에 커서를 둔다.
// 패널은 누른 즉시 다시 연다 — 기다린 뒤 열면 좁은 터미널에서 엔진이 누름에 대한 열기로 보지 않는다(TASK-010).
// 채팅 입력창에 치다 만 글이 있으면 엔진이 키보드를 넘기지 않는다 — 커서 옮기기는 덤이라, 거절되거나 실패해도 수정 칸은 그대로 둔다
export async function startEdit($: EngineInterface, title: string, item: Item) {
  const opened = $.ui.open({ id: PANE, title, focus: true })
  await setView($, view => ({
    ...view,
    adding: null,
    armedId: null,
    editing: { id: item.id, title: item.title, body: item.body },
  }))
  await opened
  const { editKey } = await readView($)
  await $.ui.focus({ requestId: PANE, key: editFieldKey('title', editKey) }).catch(() => undefined)
}

// 데스크톱 앱은 누른 버튼이 누른 결과로 사라지면 다음 첫 클릭에 반응하지 않는다(TASK-014). 동작이 끝나면 커서를
// 그 화면(site: 패널 id 또는 띠의 requestId)에 남는 버튼(key)으로 옮긴다 — 덤이라, 거절되거나 실패해도 그대로 둔다
export async function focusAfter($: EngineInterface, site: string, key: string, action: Promise<unknown>) {
  await action
  await $.ui.focus({ requestId: site, key }).catch(() => undefined)
}

// isOpen: 띠가 그릴 때 읽은 열림 상태. 열 때는 기다림 없이 $.ui.open부터 불러야 엔진이 누름에 대한 열기로
// 보고 폭과 상관없이 배치한다 — 기다린 뒤 열면 좁은 터미널(110칸 미만)에서 그리지 않는다 (spec UI.md 2절)
export async function togglePane($: EngineInterface, title: string, isOpen: boolean) {
  if (!isOpen) return openPane($, title)
  // 자기 $.ui.close에는 자기 ui.close 훅이 돌지 않을 수 있어 여기서도 닫힘을 기록한다
  await $.ui.close({ id: PANE })
  await paneClosed($)
}

// 노트를 바꿔 저장한다. 저장에 성공하면 화면 값을 바꾸고 저장된 노트를, 노트가 열리지 않았거나 실패하면 null
export async function saveChange($: EngineInterface, edit: (n: Note) => Note): Promise<Note | null> {
  const opened = await read($, session)
  if (opened === null) return null
  try {
    const saved = await saveNote($, opened.path, edit, opened.overwrite)
    await update($, note, () => saved)
    if (opened.overwrite) await update($, session, () => ({ ...opened, overwrite: false }))
    return saved
  } catch {
    return null
  }
}

// 사용자가 화면에서 바꾼 것 — 실패하면 토스트를 띄운다
async function change($: EngineInterface, text: Text, edit: (n: Note) => Note): Promise<Note | null> {
  const saved = await saveChange($, edit)
  if (saved === null) $.ui.toast(text.saveFailed)
  return saved
}

const withItem = (n: Note, id: string, edit: (item: Item) => Item): Note => ({
  ...n,
  items: n.items.map(item => (item.id === id ? edit(item) : item)),
})

const itemIn = (n: Note, id: string) => n.items.find(item => item.id === id)

// 항목을 완료한다. 그 항목의 완료 제안은 없앤다(spec DATA.md 2절)
export const completeIn = (n: Note, id: string, at: string): Note => ({
  ...withItem(n, id, item => (item.status === 'open' ? { ...item, status: 'done', doneAt: at } : item)),
  proposals: n.proposals.filter(p => !(p.kind === 'done' && p.itemId === id)),
})

// 완료한 항목을 다시 연다
export const reopenIn = (n: Note, id: string): Note =>
  withItem(n, id, item => (item.status === 'done' ? { ...item, status: 'open', doneAt: null } : item))

// 항목과 그 항목을 가리키는 완료 제안을 지운다
export const removeIn = (n: Note, id: string): Note => ({
  ...n,
  items: n.items.filter(item => item.id !== id),
  proposals: n.proposals.filter(p => !(p.kind === 'done' && p.itemId === id)),
})

// 제목·내용을 고친다. 빈 제목과 주지 않은 내용은 그대로 둔다
export const editIn = (n: Note, id: string, title: string, body?: string): Note =>
  withItem(n, id, item => ({ ...item, title: title === '' ? item.title : title, body: body ?? item.body }))

// 제안을 받는다: 새 항목 제안은 받은 시각의 항목(올린 경로 proposal)이 되고, 완료 제안은 그 항목을 완료한다
export function acceptIn(n: Note, proposal: Proposal, at: string, itemId: string): Note {
  const rest = { ...n, proposals: n.proposals.filter(p => p.id !== proposal.id) }
  if (proposal.kind === 'done') return completeIn(rest, proposal.itemId, at)
  const item: Item = {
    id: itemId,
    title: proposal.title,
    body: proposal.body,
    source: 'proposal',
    status: 'open',
    createdAt: at,
    doneAt: null,
  }
  return { ...rest, items: [...rest.items, item] }
}

export async function toggleDone($: EngineInterface, text: Text, id: string) {
  const at = isoAt(await $.clock.now())
  const saved = await change($, text, n => (itemIn(n, id)?.status === 'open' ? completeIn(n, id, at) : reopenIn(n, id)))
  if (saved === null) return
  await setView($, view => (view.openId === id ? { ...view, openId: null, editing: null, armedId: null } : view))
  const item = itemIn(saved, id)
  if (item) await tell($, item.status === 'done' ? told.completed(item) : told.reopened(item))
}

// 빈 제목은 추가하지 않고 초안을 그대로 둔다
export async function addItem($: EngineInterface, text: Text, draft: Draft) {
  const title = draft.title.trim()
  if (title === '') return
  const at = isoAt(await $.clock.now())
  const item: Item = {
    id: newId(),
    title,
    body: draft.body.trim(),
    source: 'user',
    status: 'open',
    createdAt: at,
    doneAt: null,
  }
  const saved = await change($, text, n => ({ ...n, items: [...n.items, item] }))
  if (saved === null) return
  await setView($, view => ({ ...view, adding: null }))
  await tell($, told.added(item))
}

// 제목을 비우고 저장하면 제목은 그대로 두고 내용만 저장한다
export async function saveEdit($: EngineInterface, text: Text, id: string, draft: Draft) {
  const title = draft.title.trim()
  const saved = await change($, text, n => editIn(n, id, title, draft.body.trim()))
  if (saved === null) return
  await setView($, view => ({ ...view, editing: null, editKey: newId() }))
  const item = itemIn(saved, id)
  if (item) await tell($, told.edited(item))
}

// 항목과 그 항목을 가리키는 제안을 완전히 지운다
export async function removeItem($: EngineInterface, text: Text, id: string) {
  const before = itemIn(await read($, note), id)
  const saved = await change($, text, n => removeIn(n, id))
  if (saved === null) return
  await setView($, view => ({ ...view, openId: null, armedId: null, editing: null }))
  if (before) await tell($, told.removed(before))
}

// 세션이 지운 항목의 펼침·초안을 닫는다
export async function forgetItem($: EngineInterface, id: string) {
  await setView($, view => ({
    ...view,
    openId: view.openId === id ? null : view.openId,
    armedId: view.armedId === id ? null : view.armedId,
    editing: view.editing?.id === id ? null : view.editing,
  }))
}

// 띠·패널의 추가·완료 — 제안을 받는다
export async function acceptProposal($: EngineInterface, text: Text, id: string) {
  const proposal = (await read($, note)).proposals.find(p => p.id === id)
  if (proposal === undefined) return
  const at = isoAt(await $.clock.now())
  const itemId = newId()
  const saved = await change($, text, n => {
    const latest = n.proposals.find(p => p.id === id)
    return latest === undefined ? n : acceptIn(n, latest, at, itemId)
  })
  if (saved === null) return
  const item = itemIn(saved, proposal.kind === 'new' ? itemId : proposal.itemId)
  if (item) await tell($, proposal.kind === 'new' ? told.accepted(item) : told.confirmed(item))
}

// 띠·패널의 무시·아직 — 제안만 없앤다
export async function dismissProposal($: EngineInterface, text: Text, id: string) {
  const proposal = (await read($, note)).proposals.find(p => p.id === id)
  if (proposal === undefined) return
  const saved = await change($, text, n => ({ ...n, proposals: n.proposals.filter(p => p.id !== id) }))
  if (saved === null) return
  if (proposal.kind === 'new') return tell($, told.dismissed(proposal.title))
  const item = itemIn(saved, proposal.itemId)
  if (item) await tell($, told.notYet(item))
}

